        return True
    if octets[0] == 192 and octets[1] == 168:
        return True
    return False

def parse_input_line(line):
    parts = line.strip().split('\t')
    if len(parts) < 7:
        return None
    return {
        'timestamp': parts[0],
        'src_ip': parts[1],
        'src_port': parts[2],
        'dst_ip': parts[3],
        'dst_port': parts[4] if parts[4] else None,
        'protocol': parts[5].lower(),
        'action': parts[6].lower(),
        'ts_epoch': int(parts[0])
    }

def map_action(action):
    mapping = {
        'successful': 'allow',
        'dropped': 'drop',
        'dropping': 'drop', 
        'rejected': 'deny',
        'denied': 'deny',
        'reset': 'reset'
    }
    return mapping.get(action, None)

def main():
    all_records = []
    with open('/workdir/input.txt', 'r') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            parsed = parse_input_line(line)
            if not parsed:
                continue
            if parsed['protocol'] not in ('tcp', 'udp'):
                continue
            if not is_private_ip(parsed['dst_ip']):
                continue
            if ':' in parsed['src_ip']:
                continue
            normalized_action = map_action(parsed['action'])
            if normalized_action is None:
                continue
            flow_key = (parsed['src_ip'], parsed['dst_ip'], parsed['protocol'], 
                       int(parsed['src_port']), int(parsed['dst_port']) if parsed['dst_port'] else None)
            all_records.append({
                'ts_epoch': parsed['ts_epoch'],
                'normalized_ts': datetime.fromtimestamp(parsed['ts_epoch'], tz=timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ'),
